export const DRAWING_CONCLUSIONS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu kesimpulan",q:"'Menarik kesimpulan' berarti...",options:["menggunakan petunjuk yang ada untuk memutuskan hal yang paling masuk akal","menebak jawaban secepat mungkin tanpa memikirkan petunjuk apa pun","menyalin kesimpulan teman tanpa melihat petunjuk yang ada sama sekali"],answer:0,explain:"Kesimpulan (inferensi) dibangun dari petunjuk yang kamu amati ditambah hal yang sudah kamu ketahui.",hint:"Petunjuk + pengetahuanmu → keputusan yang masuk akal."},
{n:2,type:"mcq",micro:"Petunjuk",q:"Dalam berpikir, 'petunjuk' adalah...",options:["perasaan yang kamu rasakan & tidak berhubungan dengan sesuatu yang diamati","hal kecil yang kamu amati & bisa membantumu memahami sesuatu","jawaban akhir yang harus dihafal sebelum kamu melihat apa pun"],answer:1,explain:"Petunjuk adalah bukti kecil yang kamu kumpulkan lewat pengamatan.",hint:"Sesuatu yang kamu lihat, dengar, atau temukan."},
{n:3,type:"mcq",micro:"Membaca petunjuk",q:"Kamu masuk rumah & melihat payung basah di dekat pintu. Kesimpulan yang paling masuk akal:",options:["payung itu selalu basah","seseorang menumpahkan air ke payung untuk bermain","di luar sedang atau baru saja hujan"],answer:2,explain:"Payung basah + diletakkan di dekat pintu adalah petunjuk kuat bahwa seseorang baru pulang kehujanan.",hint:"Kapan payung biasanya jadi basah?"},
{n:4,type:"tf",micro:"Kesimpulan itu pasti?",q:"Benar atau Salah: Sebuah kesimpulan selalu 100% pasti benar.",answer:false,explain:"Kesimpulan adalah dugaan cerdas berdasarkan petunjuk; ia bisa keliru bila petunjuknya kurang atau menyesatkan.",hint:"Cerdas, tapi belum tentu pasti."},
{n:5,type:"mcq",micro:"Melihat vs menyimpulkan",q:"Mana yang merupakan hal yang kamu LIHAT (pengamatan), bukan kesimpulan?",options:["'Ada air mata di pipi anak itu.'","'Anak itu baru dimarahi.'","'Anak itu sedih.'"],answer:0,explain:"Air mata di pipi adalah pengamatan langsung. 'Sedih' & 'baru dimarahi' adalah kesimpulan yang kamu tambahkan.",hint:"Mana yang bisa difoto apa adanya?"},
{n:6,type:"mcq",micro:"Bahan sebuah kesimpulan",q:"Untuk menarik kesimpulan yang baik, kamu menggabungkan petunjuk dengan...",options:["tebakan orang yang paling ramai","hal yang sudah kamu ketahui dari pengalaman","harapan tentang apa yang kamu inginkan terjadi"],answer:1,explain:"Inferensi = petunjuk yang diamati + pengetahuan latar yang relevan.",hint:"Petunjuk saja tidak cukup; kamu perlu bekal pengetahuan."},
{n:7,type:"mcq",micro:"Banyak petunjuk",q:"Kesimpulan biasanya lebih kuat bila...",options:["satu petunjuk sudah sangat jelas & kamu tidak perlu mencari lagi","kamu merasa yakin sekali walau petunjuknya hanya satu & lemah","beberapa petunjuk berbeda menunjuk ke arah yang sama"],answer:2,explain:"Semakin banyak petunjuk yang cocok, semakin kecil kemungkinan kesimpulanmu keliru.",hint:"Satu petunjuk lemah; beberapa petunjuk yang sejalan lebih meyakinkan."},
{n:8,type:"mcq",micro:"Ramalan sebagai inferensi",q:"Melihat langit gelap & angin kencang, kamu berkata 'sepertinya akan hujan'. Ini disebut...",options:["prediksi — kesimpulan tentang apa yang akan terjadi","aturan","pengamatan"],answer:0,explain:"Prediksi adalah inferensi yang diarahkan ke masa depan berdasarkan petunjuk sekarang.",hint:"Kesimpulan tentang nanti."},
{n:9,type:"tf",micro:"Kesimpulan bisa salah",q:"Benar atau Salah: Kesimpulan yang tadinya masuk akal bisa ternyata keliru setelah kita tahu lebih banyak.",answer:true,explain:"Itu wajar. Orang yang berpikir baik bersedia memperbaiki kesimpulannya saat muncul petunjuk baru.",hint:"Petunjuk baru bisa mengubah gambaran."},
{n:10,type:"mcq",micro:"Petunjuk sehari-hari",q:"Mangkuk makan anjing kosong & anjing menggonggong di dekat mangkuknya sambil menatapmu. Kesimpulan paling masuk akal:",options:["anjing itu ingin bermain bola","anjing itu mungkin lapar & minta makan","anjing itu marah pada mangkuknya"],answer:1,explain:"Mangkuk kosong + gonggongan di dekatnya + tatapan adalah petunjuk yang sejalan menuju 'lapar'.",hint:"Gabungkan ketiga petunjuk itu."},
{n:11,type:"open",micro:"Membaca sebuah adegan",q:"Bayangkan kamu masuk dapur & melihat: kursi terguling, remah kue di lantai, & pintu belakang terbuka. Tuliskan satu kesimpulan yang masuk akal & sebutkan petunjuk mana yang mendukungnya.",explain:"Kesimpulan yang baik menyebut petunjuk pendukungnya & mengakui bahwa masih ada kemungkinan lain.",hint:"Satu kesimpulan + petunjuk pendukung + akui ketidakpastian.",sample:"Kesimpulan: sepertinya ada yang buru-buru mengambil kue lalu keluar lewat pintu belakang. Petunjuk: remah kue menunjukkan seseorang makan kue di dapur, kursi terguling menunjukkan gerakan tergesa, & pintu belakang terbuka menunjukkan ke mana orang itu pergi. Tapi ini belum pasti — bisa jadi angin membuka pintu & hewan peliharaan menjatuhkan kue."},
{n:12,type:"mcq",micro:"Satu petunjuk, banyak arti",q:"Kamu melihat lantai basah di lorong sekolah. Sikap berpikir yang tepat:",options:["yakin pasti ada yang sengaja menumpahkan air & langsung mencari siapa pelakunya untuk ditegur di depan kelas","menyimpulkan sekolah pasti bocor & memanggil petugas tanpa memeriksa apa-apa dulu atau mencari petunjuk lain","sadar bahwa penyebabnya bisa banyak (pel, bocor, tumpahan, hujan terbawa sepatu) & butuh petunjuk lain"],answer:2,explain:"Satu petunjuk sering cocok dengan beberapa penjelasan. Jangan langsung memilih satu tanpa bukti tambahan.",hint:"Berapa banyak cara lantai bisa jadi basah?"},
{n:13,type:"tf",micro:"Tebakan vs inferensi",q:"Benar atau Salah: Setiap tebakan sama bagusnya, karena semua kesimpulan hanyalah menebak.",answer:false,explain:"Inferensi yang didukung banyak petunjuk yang relevan jauh lebih kuat daripada tebakan tanpa dasar.",hint:"Ada tebakan berdasar & tebakan kosong."},
{n:14,type:"mcq",micro:"Jejak",q:"Ada jejak kaki berlumpur dari pintu menuju dapur. Kesimpulan langsung yang paling aman:",options:["seseorang berjalan masuk dengan sepatu kotor","seseorang sengaja mengotori lantai dapur untuk membuat orang lain marah","seekor hewan besar berjalan sendiri dari pintu menuju dapur tadi malam"],answer:0,explain:"Petunjuk hanya mendukung 'seseorang berjalan dengan sepatu berlumpur'. Menyebut siapa atau motifnya butuh petunjuk lain.",hint:"Simpulkan hanya sejauh yang didukung petunjuk."},
{n:15,type:"mcq",micro:"Kesimpulan yang paling didukung",q:"Petunjuk: piring kotor di wastafel, panci masih hangat, bau bawang di dapur. Kesimpulan paling didukung:",options:["kompor rusak","seseorang baru saja memasak","besok ada pesta"],answer:1,explain:"Ketiga petunjuk (piring, panci hangat, bau masakan) sama-sama menunjuk pada kegiatan memasak yang baru terjadi.",hint:"Cari kesimpulan yang cocok dengan SEMUA petunjuk."},
{n:16,type:"mcq",micro:"Menguatkan kesimpulan",q:"Kamu menyimpulkan 'Rina suka menggambar'. Petunjuk mana yang paling menguatkannya?",options:["Rina sering bercerita bahwa ia suka makan es krim di kantin","Rina memiliki banyak buku cerita yang tersusun rapi di rak","buku Rina penuh sketsa & ia sering menggambar saat istirahat"],answer:2,explain:"Petunjuk yang relevan & berulang (buku penuh sketsa, sering menggambar) menguatkan kesimpulan. Warna baju tidak relevan.",hint:"Mana petunjuk yang benar-benar berhubungan dengan menggambar?"},
{n:17,type:"order",micro:"Langkah menyimpulkan",q:"Urutkan langkah menarik kesimpulan yang baik:",items:["Amati petunjuk yang ada dengan teliti","Ingat pengetahuan yang berhubungan dengan petunjuk itu","Pikirkan penjelasan yang paling cocok dengan semua petunjuk","Sampaikan kesimpulan sambil menyebut petunjuk pendukungnya"],answer:[0,1,2,3],explain:"Amati → hubungkan dengan pengetahuan → pilih penjelasan terbaik → sampaikan dengan alasannya.",hint:"Mengamati dulu, menyampaikan terakhir."},
{n:18,type:"mcq",micro:"Perasaan dari tindakan",q:"Seorang tokoh cerita membanting pintu, melipat tangan, & menjawab dengan pendek. Kesimpulan yang masuk akal tentang perasaannya:",options:["ia mungkin sedang kesal atau marah","ia sedang mengantuk","ia sedang gembira"],answer:0,explain:"Penulis sering menunjukkan perasaan lewat tindakan. Membanting pintu & jawaban pendek adalah petunjuk kekesalan.",hint:"Apa yang biasanya dilakukan orang saat kesal?"},
{n:19,type:"tf",micro:"Bersedia meninjau ulang",q:"Benar atau Salah: Jika muncul petunjuk baru yang tidak cocok, sebaiknya kita tetap mempertahankan kesimpulan lama apa pun yang terjadi.",answer:false,explain:"Sebaliknya, kesimpulan yang baik ditinjau ulang saat petunjuk baru muncul. Keras kepala membuat kita terus salah.",hint:"Petunjuk baru → tinjau ulang."},
{n:20,type:"mcq",micro:"Ringkasan Fondasi",q:"Inti menarik kesimpulan adalah...",options:["memilih jawaban yang paling disukai & merasa pasti benar, tanpa perlu memeriksa petunjuk lain yang mungkin bertentangan dengan pilihan itu","menggabungkan petunjuk & pengetahuan untuk memilih penjelasan paling masuk akal, sambil sadar itu bisa keliru","menebak sesuatu secara acak & menganggapnya pasti benar selama tidak ada orang lain yang membantah tebakan itu"],answer:1,explain:"Inferensi adalah jembatan antara apa yang kita amati & apa yang belum kita lihat langsung — kuat bila didasari petunjuk, tetap terbuka untuk diperbaiki.",hint:"Petunjuk + pengetahuan → penjelasan terbaik, tetap terbuka."},
{n:21,type:"classify",micro:"Pengamatan atau kesimpulan",q:"Kelompokkan setiap pernyataan:",items:["Rumput di lapangan basah","Semalam pasti hujan","Ada 12 anak berbaris di depan kelas","Anak-anak itu akan mengikuti lomba"],groups:["Pengamatan","Kesimpulan"],answer:{"Pengamatan":["Rumput di lapangan basah","Ada 12 anak berbaris di depan kelas"],"Kesimpulan":["Semalam pasti hujan","Anak-anak itu akan mengikuti lomba"]},explain:"Pengamatan bisa dilihat langsung apa adanya; kesimpulan adalah tambahan pemikiran kita atas pengamatan itu.",hint:"Bisa difoto apa adanya = pengamatan."},
{n:22,type:"mcq",micro:"Mengenali pengamatan",q:"Mana yang murni pengamatan?",options:["'Ia pasti sedang sakit parah & perlu dirawat.'","'Ia kurang tidur karena begadang menonton film semalaman.'","'Matanya merah & ia menguap tiga kali.'"],answer:2,explain:"Mata merah & menguap adalah hal yang teramati. Alasan 'tidur larut' & 'tidak suka' adalah kesimpulan.",hint:"Buang bagian 'karena' & 'tidak suka'."},
{n:23,type:"mcq",micro:"Mengenali kesimpulan",q:"Mana yang merupakan kesimpulan?",options:["Kotak-kotak itu berisi hadiah ulang tahun","Kotak itu dibungkus kertas berwarna","Ada tiga kotak di atas meja"],answer:0,explain:"'Berisi hadiah ulang tahun' tidak terlihat langsung — itu tafsiran kita atas kotak yang dibungkus.",hint:"Mana yang tidak bisa kamu pastikan tanpa membuka?"},
{n:24,type:"mcq",micro:"Membaca adegan",q:"Di meja ada remah roti, piring kosong, & gelas susu tinggal setengah. Kesimpulan paling masuk akal:",options:["seseorang sedang tidur di sini karena gelasnya masih berisi","seseorang baru saja makan roti & minum susu di sini","tidak ada yang bisa disimpulkan karena benda di meja tak berhubungan"],answer:1,explain:"Remah + piring kosong + gelas berkurang isinya adalah petunjuk yang sejalan menuju 'seseorang baru sarapan'.",hint:"Apa yang menghubungkan ketiga petunjuk?"},
{n:25,type:"tf",micro:"Cukupkah petunjuknya",q:"Benar atau Salah: Melihat satu anak berlari di koridor sudah cukup untuk menyimpulkan bahwa 'semua anak di sekolah ini suka berlari di koridor'.",answer:false,explain:"Satu contoh tidak cukup untuk kesimpulan tentang semua orang. Itu melompat terlalu jauh dari petunjuk.",hint:"Satu anak ≠ semua anak."},
{n:26,type:"mcq",micro:"Petunjuk terlalu sedikit",q:"Kamu hanya tahu bahwa 'Doni tidak masuk sekolah hari ini'. Kesimpulan yang jujur:",options:["Doni pasti sakit","Doni pasti bolos","belum cukup petunjuk untuk tahu alasannya"],answer:2,explain:"Dengan satu fakta saja, jujur mengakui 'belum tahu' lebih baik daripada memilih satu penjelasan tanpa dasar.",hint:"Berapa alasan mungkin seseorang tidak masuk?"},
{n:27,type:"mcq",micro:"Kesimpulan berlebihan",q:"Petunjuk: Sari mendapat nilai bagus di ulangan Matematika hari ini. Kesimpulan yang BERLEBIHAN (melampaui petunjuk):",options:["Sari adalah anak terpintar di sekolah & tidak pernah salah","Sari mendapat nilai bagus di Matematika hari ini","Sari mungkin belajar atau memahami materi hari ini"],answer:0,explain:"Satu nilai bagus tidak mendukung klaim besar 'terpintar di sekolah & tidak pernah salah'. Kesimpulan harus sepadan dengan petunjuk.",hint:"Mana yang jauh lebih besar dari buktinya?"},
{n:28,type:"mcq",micro:"Pisahkan lihat & pikir",q:"Cara terbaik memeriksa kesimpulanmu sendiri tentang sebuah gambar:",options:["langsung menceritakan kesimpulanmu kepada teman & minta mereka setuju","tuliskan dulu apa yang benar-benar terlihat, lalu pisahkan bagian yang merupakan tafsiranmu","mengubah gambar supaya cocok dengan kesimpulanmu & menyembunyikan yang tidak cocok"],answer:1,explain:"Memisahkan 'yang kulihat' dari 'yang kupikirkan' membuat kamu sadar bagian mana yang masih perlu bukti.",hint:"Dua kolom: terlihat | ditafsirkan."},
{n:29,type:"mcq",micro:"Petunjuk relevan",q:"Kamu ingin menyimpulkan apakah toko sudah buka. Petunjuk paling RELEVAN:",options:["toko itu berada di dekat sekolah & selalu ramai di akhir pekan","papan namanya berwarna cerah & ada gambar kue besar di depannya","lampu di dalam menyala, pintu terbuka, & ada pembeli keluar-masuk"],answer:2,explain:"Petunjuk yang relevan berhubungan langsung dengan pertanyaannya. Lampu menyala & pembeli keluar-masuk menjawab 'buka atau tidak'.",hint:"Mana yang benar-benar menandai 'buka'?"},
{n:30,type:"order",micro:"Dari petunjuk lemah ke kuat",q:"Urutkan kesimpulan berikut dari yang paling LEMAH ke paling KUAT dukungannya (petunjuk: seseorang menyimpulkan Budi lapar):",items:["Budi pernah lapar minggu lalu","Budi belum makan sejak pagi","Budi belum makan sejak pagi & tadi bilang perutnya keroncongan","Budi belum makan sejak pagi, bilang lapar, & terus melihat ke arah kantin"],answer:[0,1,2,3],explain:"Semakin banyak petunjuk yang relevan & sejalan, semakin kuat kesimpulannya.",hint:"Hitung jumlah petunjuk relevan di tiap pilihan."},
{n:31,type:"mcq",micro:"Dua petunjuk sejalan",q:"Petunjuk: (1) tanah di pot kering & retak, (2) daun tanaman layu menggantung. Kesimpulan yang didukung KEDUA petunjuk:",options:["tanaman itu kekurangan air","tanaman itu terlalu banyak disiram","pot itu terlalu besar"],answer:0,explain:"Tanah kering & daun layu keduanya cocok dengan 'kurang air'. Kesimpulan terbaik menjelaskan semua petunjuk sekaligus.",hint:"Penjelasan mana yang menutup kedua petunjuk?"},
{n:32,type:"tf",micro:"Menyimpulkan maksud penulis",q:"Benar atau Salah: Saat membaca, kita kadang harus menyimpulkan hal yang tidak ditulis langsung oleh penulis, dari petunjuk dalam teks.",answer:true,explain:"Penulis sering 'menunjukkan, bukan memberi tahu'. Pembaca menyimpulkan perasaan, waktu, atau alasan dari petunjuk cerita.",hint:"'Menunjukkan, bukan memberi tahu.'"},
{n:33,type:"mcq",micro:"Inferensi dalam bacaan",q:"Teks: 'Andi menutup buku rapornya, menunduk, & tidak berkata apa-apa sepanjang perjalanan pulang.' Kesimpulan yang masuk akal:",options:["Andi pasti sengaja ingin membuat orang tuanya marah","Andi mungkin kecewa dengan hasil rapornya","Andi pasti sedang sangat gembira dengan hasil rapornya"],answer:1,explain:"Menunduk & diam sepanjang jalan adalah petunjuk kekecewaan, walau penulis tidak menyebut kata 'kecewa'.",hint:"Apa yang ditunjukkan tindakan Andi?"},
{n:34,type:"mcq",micro:"Inferensi dalam sains",q:"Kamu mengamati tanaman di jendela condong ke arah kaca. Kesimpulan ilmiah yang masuk akal:",options:["tanaman itu sedang kehausan & ingin menjatuhkan diri","tanaman itu ingin menyentuh kaca karena merasa kesepian","tanaman itu tumbuh mengarah ke cahaya"],answer:2,explain:"Tumbuhan tumbuh ke arah sumber cahaya (fototropisme). Petunjuk 'condong ke jendela' cocok dengan penjelasan ini.",hint:"Apa yang ada di balik kaca jendela?"},
{n:35,type:"mcq",micro:"Memilih kesimpulan terbaik",q:"Petunjuk: rumput taman diinjak membentuk jalur, ada bungkus jajan di sepanjang jalur itu, & pagar samping penyok. Kesimpulan paling didukung:",options:["orang sering memakai jalur pintas itu sambil jajan & melewati pagar","pagar penyok karena angin besar & bungkus jajan terbawa angin ke jalur itu","penjaga sengaja menaruh bungkus jajan sebagai tanda arah ke pagar yang rusak"],answer:0,explain:"Jalur terinjak + sampah jajan + pagar penyok semuanya konsisten dengan 'sering dilewati sebagai jalan pintas'.",hint:"Kesimpulan mana yang menjelaskan ketiganya?"},
{n:36,type:"open",micro:"Lihat vs tafsir",q:"Lihat kalimat ini: 'Seorang anak berdiri di depan pintu kelas yang sudah terkunci, memegang tas, sambil melihat jam.' Tuliskan 2 hal yang benar-benar disebutkan (pengamatan) & 2 hal yang merupakan kesimpulanmu.",explain:"Memisahkan pengamatan dari kesimpulan membantu kita tahu bagian mana yang masih perlu dicek.",hint:"2 fakta tertulis + 2 tafsiranmu.",sample:"Pengamatan: (1) anak itu memegang tas, (2) pintu kelas terkunci & ia melihat jam. Kesimpulan: (1) anak itu mungkin terlambat & kelas sudah dimulai atau sudah selesai, (2) ia mungkin cemas karena terus melihat jam. Kesimpulan ini masuk akal tapi belum pasti — bisa saja ia datang lebih awal & menunggu."},
{n:37,type:"mcq",micro:"Mungkin ≠ terbukti",q:"'Mungkin adikku yang menghabiskan biskuit' — pernyataan ini...",options:["sudah pasti benar karena adik sering terlihat membawa biskuit","baru satu kemungkinan; masih perlu petunjuk untuk memastikan","pasti salah karena hanya orang dewasa yang boleh memakan biskuit"],answer:1,explain:"Sesuatu yang mungkin belum tentu benar. Kemungkinan perlu diuji dengan petunjuk sebelum jadi kesimpulan.",hint:"'Mungkin' adalah awal, bukan akhir."},
{n:38,type:"tf",micro:"Menahan kesimpulan",q:"Benar atau Salah: Kalau petunjuk yang ada masih terlalu sedikit, mengatakan 'aku belum bisa menyimpulkan' adalah sikap berpikir yang buruk.",answer:false,explain:"Sebaliknya, menahan diri saat bukti kurang adalah tanda berpikir yang matang, bukan kelemahan.",hint:"Sabar menunggu bukti = berpikir baik."},
{n:39,type:"mcq",micro:"Kapan menunda",q:"Kamu melihat dua anak berdebat & satu menangis. Sebelum menyimpulkan siapa yang salah, sebaiknya...",options:["menyimpulkan yang menangis pasti korban","langsung menyalahkan yang badannya lebih besar","dengarkan kedua pihak & cari petunjuk lain dulu"],answer:2,explain:"Petunjuk awal (siapa menangis, siapa lebih besar) bisa menyesatkan. Kumpulkan keterangan kedua pihak sebelum menyimpulkan.",hint:"Dengar dua sisi sebelum memutuskan."},
{n:40,type:"mcq",micro:"Ringkasan Pemahaman",q:"Saat mengevaluasi sebuah kesimpulan, pertanyaan paling berguna:",options:["'Apakah petunjuknya cukup, relevan, & benar-benar mendukung kesimpulan ini?'","'Siapa yang paling banyak setuju dengan kesimpulan ini?'","'Apakah kesimpulan ini terdengar paling menarik untuk diceritakan?'"],answer:0,explain:"Kualitas kesimpulan diukur dari kualitas & kecukupan petunjuknya, bukan dari keinginan kita atau suara terbanyak.",hint:"Cukup? Relevan? Benar-benar mendukung?"},
{n:41,type:"mcq",micro:"Terapan: jejak di kebun",q:"Di kebun ada jejak sepatu kecil menuju pohon mangga, ranting patah di bawah pohon, & satu mangga tergeletak setengah terkupas. Kesimpulan paling masuk akal:",options:["seekor monyet besar memanjat pohon & sengaja menjatuhkan mangga","seorang anak memanjat mengambil mangga & meninggalkannya","tukang kebun sedang memanen semua mangga dengan tangga panjang"],answer:1,explain:"Jejak kecil + ranting patah + mangga setengah terkupas adalah petunjuk yang sejalan menuju 'anak memanjat & mengambil mangga'.",hint:"Satu cerita yang menutup ketiga petunjuk."},
{n:42,type:"mcq",micro:"Terapan: teman diam",q:"Temanmu yang biasanya ceria hari ini diam, tidak makan bekalnya, & menjawab singkat. Langkah yang bijak:",options:["menyimpulkan ia sombong karena tidak mau makan bersama & menghindarinya","menganggap ia sedang berpura-pura & menunggu sampai ia bercerita sendiri tanpa bertanya","menduga ada yang mengganggunya & bertanya baik-baik 'kamu kelihatan murung, ada apa?'"],answer:2,explain:"Petunjuk menunjukkan ada sesuatu, tapi bukan APA. Menanyakan langsung lebih baik daripada menebak lalu bertindak.",hint:"Kesimpulan sementara → periksa dengan bertanya."},
{n:43,type:"mcq",micro:"Terapan: meja belajar",q:"Di meja belajar kakak ada buku terbuka, pensil di atas kertas berisi setengah soal, & segelas air. Kesimpulan yang paling aman:",options:["kakak sedang atau baru saja mengerjakan tugas & berhenti sebentar","kakak pasti sudah selesai semua tugas & sedang bersantai santai","kakak menyuruh orang lain mengerjakan soalnya & hanya menonton saja"],answer:0,explain:"Buku terbuka + soal setengah jadi + gelas air cocok dengan 'sedang mengerjakan tugas & rehat sejenak'.",hint:"Simpulkan hanya sejauh petunjuk membawamu."},
{n:44,type:"open",micro:"Terapan: teman absen",q:"Teman sebangkumu tidak masuk hari ini & tasnya masih tertinggal di kelas dari kemarin. Tuliskan minimal dua kemungkinan penjelasan, lalu satu cara mencari tahu yang benar.",explain:"Saat petunjuk cocok dengan beberapa penjelasan, sebutkan pilihannya & cari cara memeriksanya, jangan langsung pilih satu.",hint:"≥2 kemungkinan + 1 cara memastikan.",sample:"Kemungkinan: (1) ia sakit mendadak & lupa membawa tasnya pulang kemarin, (2) ia ada urusan keluarga dadakan, (3) ia lupa tasnya & baru sadar di rumah tapi tidak sempat mengambil. Cara mencari tahu: menanyakan ke wali kelas atau menghubungi keluarganya lewat guru, bukan menyebar dugaan ke teman-teman."},
{n:45,type:"mcq",micro:"Terapan: nada pesan",q:"Kamu mengirim pesan panjang, temanmu hanya membalas 'ok.' Kesimpulan yang bijak tentang nada pesan itu:",options:["temanmu pasti marah atau tidak peduli padamu karena hanya menulis 'ok', jadi sebaiknya kamu berhenti menghubunginya","nada pesan singkat sulit dibaca; bisa saja ia sibuk, buru-buru, atau memang biasa membalas pendek","temanmu pasti sedang gembira sekali & hanya malas mengetik panjang-panjang, jadi tidak ada yang perlu dipikirkan"],answer:1,explain:"Teks menghilangkan nada suara & wajah, sehingga petunjuknya sedikit. Menyimpulkan emosi dari satu kata mudah keliru.",hint:"Berapa banyak petunjuk yang benar-benar ada di 'ok.'?"},
{n:46,type:"order",micro:"Terapan: menyimpulkan dengan hati-hati",q:"Urutkan langkah menyimpulkan siapa yang meninggalkan sepeda di depan gerbang:",items:["Catat petunjuk: warna, stiker, keranjang, kondisi sepeda","Ingat siapa yang punya sepeda mirip itu","Cocokkan petunjuk dengan pemilik yang mungkin","Konfirmasi langsung ke orang itu sebelum menyimpulkan"],answer:[0,1,2,3],explain:"Kumpulkan petunjuk → hubungkan dengan yang kamu tahu → susun dugaan → konfirmasi.",hint:"Konfirmasi ada di akhir."},
{n:47,type:"mcq",micro:"Terapan: pot jatuh",q:"Pot bunga di ambang jendela jatuh & pecah. Jendela terbuka, angin bertiup kencang, & kucing tidur nyenyak di sofa jauh dari jendela. Kesimpulan paling masuk akal:",options:["kucing diam-diam menjatuhkan pot lalu pura-pura tidur di sofa","seseorang sengaja menjatuhkan pot lewat jendela terbuka tadi pagi","angin kencang dari jendela terbuka menjatuhkan pot"],answer:2,explain:"Kucing yang tidur jauh dari jendela tidak cocok sebagai penyebab. Angin kencang + jendela terbuka adalah penjelasan yang paling pas dengan semua petunjuk.",hint:"Buang penjelasan yang bertentangan dengan petunjuk."},
{n:48,type:"tf",micro:"Terapan: satu kali kejadian",q:"Benar atau Salah: Karena hari ini kamu melihat kakak kelas membuang sampah sembarangan satu kali, wajar menyimpulkan 'semua kakak kelas jorok'.",answer:false,explain:"Satu kejadian pada satu orang tidak mendukung kesimpulan tentang seluruh kelompok. Itu generalisasi tergesa.",hint:"Satu orang, satu kali ≠ semua orang."},
{n:49,type:"mcq",micro:"Terapan: es mencair",q:"Di lab, es batu dalam gelas mencair jauh lebih cepat dari biasanya. Kesimpulan yang masuk akal untuk diselidiki:",options:["ruangan mungkin lebih hangat dari biasanya hari ini","es itu palsu","gelasnya tidak suka es"],answer:0,explain:"Laju mencair yang cepat adalah petunjuk suhu sekitar yang lebih tinggi. Itu kesimpulan yang bisa diuji dengan termometer.",hint:"Apa yang membuat es mencair lebih cepat?"},
{n:50,type:"mcq",micro:"Terapan: tokoh bersiap",q:"Dalam cerita: 'Maya memasukkan baju ke koper, memeriksa tiket dua kali, & memeluk anjingnya lama-lama.' Kesimpulan yang masuk akal:",options:["Maya baru pulang dari liburan & sedang membereskan kopernya","Maya akan bepergian jauh & agak berat meninggalkan anjingnya","Maya akan menyerahkan anjingnya kepada orang lain secara permanen"],answer:1,explain:"Koper + tiket + pelukan lama adalah petunjuk yang menunjuk pada 'akan pergi jauh & sedih berpisah'.",hint:"Gabungkan ketiga tindakan Maya."},
{n:51,type:"mcq",micro:"Terapan: membaca grafik",q:"Grafik menunjukkan jumlah buku yang dipinjam dari perpustakaan naik terus setiap bulan selama satu semester. Kesimpulan yang didukung data:",options:["semua murid di sekolah ini kini sudah membaca semua buku","perpustakaan ini pasti akan kehabisan buku sebelum semester berakhir","minat meminjam buku di sekolah ini sedang meningkat semester ini"],answer:2,explain:"Data hanya mendukung pernyataan tentang tren peminjaman semester ini, bukan klaim tentang 'semua murid' atau masa depan perpustakaan.",hint:"Simpulkan sebatas yang ditunjukkan grafik."},
{n:52,type:"open",micro:"Terapan: adegan kelas",q:"Kamu masuk kelas & melihat: papan tulis penuh tulisan yang belum dihapus, beberapa kursi belum tertata, & seorang guru mengumpulkan kertas ulangan. Tuliskan kesimpulanmu tentang apa yang baru terjadi & petunjuk pendukungnya.",explain:"Kesimpulan yang baik menyebut petunjuk untuk tiap bagiannya & mengakui bagian yang masih belum pasti.",hint:"Apa yang terjadi + petunjuk tiap bagian.",sample:"Kesimpulan: sepertinya baru saja selesai ulangan atau pelajaran, & kelas belum dirapikan. Petunjuk: guru mengumpulkan kertas ulangan menunjukkan ada ujian, papan penuh tulisan menunjukkan pelajaran baru berlangsung, kursi berantakan menunjukkan murid baru saja pergi terburu-buru. Belum pasti apakah itu ulangan atau latihan biasa."},
{n:53,type:"mcq",micro:"Terapan: susu tumpah",q:"Ada susu tumpah di lantai & balita sedang berdiri di sebelahnya memegang gelas kosong. Kesimpulan yang masuk akal, disampaikan dengan tenang:",options:["kemungkinan besar susunya tak sengaja tumpah saat balita memegang gelas — bersihkan & bantu ia","balita itu pasti sengaja menumpahkan susu & harus dimarahi agar tidak mengulang","susu itu pasti tumpah karena gelasnya rusak & balita tidak ada hubungannya sama sekali"],answer:0,explain:"Petunjuk mendukung 'tak sengaja', bukan niat jahat. Kesimpulan sebaiknya adil & sepadan dengan petunjuk.",hint:"Petunjuk menunjukkan kecelakaan, bukan niat."},
{n:54,type:"tf",micro:"Terapan: menebak isi kado",q:"Benar atau Salah: Kado berbentuk kotak keras & berbunyi 'klotak' saat digoyang membuat kesimpulan 'isinya mungkin mainan atau benda keras' lebih masuk akal daripada 'isinya kain'.",answer:true,explain:"Bentuk keras & bunyi benda bergerak adalah petunjuk yang lebih cocok dengan benda padat daripada kain yang lembut & senyap.",hint:"Kain tidak berbunyi 'klotak'."},
{n:55,type:"mcq",micro:"Terapan: arti kata dari konteks",q:"Kalimat: 'Jalanan begitu becek sehingga sepatuku terbenam & sulit ditarik.' Dari petunjuk kalimat, 'becek' kemungkinan berarti...",options:["kering & berdebu","berlumpur & basah","panas & retak"],answer:1,explain:"Petunjuk 'sepatu terbenam & sulit ditarik' cocok dengan tanah berlumpur basah, bukan kering.",hint:"Apa jenis tanah yang membuat sepatu terbenam?"},
{n:56,type:"order",micro:"Terapan: memeriksa dugaan",q:"Urutkan langkah saat kamu menduga 'jendela kelas dibiarkan terbuka semalam sehingga lantai basah':",items:["Amati: lantai basah hanya di dekat jendela, tirai ikut lembap","Ingat: semalam hujan & angin dari arah jendela itu","Simpulkan sementara: air masuk lewat jendela yang terbuka","Periksa: tanya petugas apakah jendela memang terbuka semalam"],answer:[0,1,2,3],explain:"Amati pola petunjuk → hubungkan dengan yang diketahui → dugaan sementara → periksa kebenarannya.",hint:"Periksa di akhir, amati di awal."},
{n:57,type:"mcq",micro:"Terapan: tanda hujan",q:"Petunjuk: langit mendung tebal, semut berbaris naik ke tempat tinggi, udara terasa lembap & angin berubah arah. Kesimpulan/prediksi yang masuk akal:",options:["cuaca akan cerah & panas terik sepanjang hari ini","tidak ada yang bisa diprediksi dari tanda-tanda alam itu sama sekali","hujan mungkin akan turun tak lama lagi"],answer:2,explain:"Beberapa petunjuk cuaca yang sejalan memperkuat prediksi hujan. Tetap sebuah prediksi, bukan kepastian.",hint:"Petunjuk mana yang mengarah ke hujan?"},
{n:58,type:"mcq",micro:"Terapan: memastikan kesimpulan",q:"Kamu menyimpulkan 'lampu kamar mati karena bohlamnya putus'. Informasi tambahan yang paling membantu memastikan:",options:["apakah lampu lain di rumah menyala (berarti bukan listrik padam) & apakah bohlam menghitam","jam berapa sekarang","warna dinding kamar"],answer:0,explain:"Petunjuk pembeda: kalau lampu lain menyala, penyebabnya bukan listrik padam; bohlam menghitam menguatkan 'putus'.",hint:"Cari petunjuk yang membedakan dua penyebab."},
{n:59,type:"tf",micro:"Terapan: menuduh tanpa bukti",q:"Benar atau Salah: Menyimpulkan 'pasti si A yang mengambil pensilku' hanya karena A duduk paling dekat adalah kesimpulan yang lemah & bisa tidak adil.",answer:true,explain:"Kedekatan tempat duduk adalah petunjuk sangat lemah. Menuduh berdasar itu bisa merugikan orang yang tidak bersalah.",hint:"Dekat ≠ bukti."},
{n:60,type:"mcq",micro:"Ringkasan Penerapan",q:"Saat menerapkan inferensi pada situasi nyata yang melibatkan orang, langkah tambahan yang penting:",options:["langsung yakin kesimpulanmu benar karena kamu punya banyak petunjuk, lalu bertindak cepat supaya masalah segera selesai","perlakukan kesimpulan sebagai sementara & periksa dengan bertanya sebelum menuduh atau bertindak","menyebarkan kesimpulanmu kepada teman-teman supaya mereka ikut setuju sebelum kamu bertanya kepada orang yang bersangkutan"],answer:1,explain:"Saat menyangkut orang lain, kesimpulan yang salah bisa menyakiti. Konfirmasi dulu sebelum bertindak.",hint:"Dugaan sementara → konfirmasi → baru bertindak."},
{n:61,type:"mcq",micro:"Melompat ke kesimpulan",q:"'Melompat ke kesimpulan' artinya...",options:["menunggu semua petunjuk terkumpul sebelum memutuskan apa pun","menyebutkan banyak kemungkinan sebelum mengambil keputusan akhir","memutuskan sesuatu sebelum petunjuknya cukup untuk mendukungnya"],answer:2,explain:"Melompat ke kesimpulan = jarak antara petunjuk & keputusan terlalu jauh; buktinya belum sepadan.",hint:"Keputusan mendahului bukti."},
{n:62,type:"mcq",micro:"Satu petunjuk, banyak penjelasan",q:"Kamu melihat mata seorang teman berkaca-kaca. Sikap penalaran yang baik:",options:["sadar bahwa mata berkaca-kaca bisa karena sedih, tertawa, menguap, kelilipan, atau alergi — perlu petunjuk lain","yakin ia sedih karena kehilangan sesuatu & langsung menghiburnya dengan menyebut kehilangan itu","menyimpulkan ia sedang berbohong tentang perasaannya & menegurnya di depan teman lain"],answer:0,explain:"Satu petunjuk sering punya banyak penyebab. Menyebut beberapa kemungkinan menahan kita dari kesimpulan tergesa.",hint:"Berapa cara mata bisa berair?"},
{n:63,type:"mcq",micro:"Hanya melihat yang cocok",q:"Kamu sudah menduga 'Rio tidak suka kerja kelompok'. Lalu kamu hanya mengingat saat Rio diam, & melupakan saat ia membantu banyak. Kesalahan berpikir ini disebut...",options:["mengumpulkan semua bukti","kecenderungan hanya memperhatikan petunjuk yang cocok dengan dugaan kita (bias konfirmasi)","berpikir terbuka"],answer:1,explain:"Bias konfirmasi membuat kita menyaring petunjuk: yang mendukung dugaan diingat, yang melawan diabaikan.",hint:"Menyimpan bukti yang cocok, membuang yang tidak."},
{n:64,type:"tf",micro:"Bukti yang melawan",q:"Benar atau Salah: Untuk menguji kesimpulan dengan jujur, kita juga harus mencari petunjuk yang mungkin membuktikan kesimpulan itu salah.",answer:true,explain:"Mencari bukti yang melawan (bukan cuma yang mendukung) adalah inti berpikir kritis yang jujur.",hint:"Coba patahkan dugaanmu sendiri."},
{n:65,type:"mcq",micro:"Meninjau ulang",q:"Kamu menyimpulkan pintu gerbang dikunci karena penjaga lupa. Lalu kamu tahu penjaga sedang menolong anak yang jatuh di dekat situ. Sikap yang tepat:",options:["tetap pada kesimpulan awal bahwa penjaga lupa & ia pantas ditegur","membuang semua petunjuk lain & mencari pelaku baru yang sengaja mengunci gerbang","perbarui kesimpulan: gerbang belum dibuka karena penjaga sedang menangani hal mendesak"],answer:2,explain:"Petunjuk baru yang penting harus mengubah kesimpulan. Bertahan hanya demi gengsi membuat kita keliru.",hint:"Fakta baru → kesimpulan baru."},
{n:66,type:"mcq",micro:"Kuat vs lemah",q:"Mana kesimpulan yang LEBIH KUAT?",options:["'Ada genangan di teras, keran taman menetes, & selang tergeletak menyala kecil — sepertinya air berasal dari keran, bukan hujan.'","'Rumput basah & ada genangan di jalan depan rumah, jadi hujan pasti turun semalam di seluruh kota tanpa terkecuali satu tempat pun.'","'Teras basah, jadi pasti ada orang yang sengaja menyiram teras itu untuk mengganggu penghuni rumah yang sedang tidur nyenyak semalam.'"],answer:0,explain:"Kesimpulan kuat menimbang beberapa petunjuk & memilih penjelasan yang paling pas, bukan melompat ke satu sebab dramatis.",hint:"Mana yang mempertimbangkan lebih banyak petunjuk?"},
{n:67,type:"mcq",micro:"Penjelasan alternatif",q:"Temanmu tidak membalas sapaanmu di koridor. Selain 'ia marah padaku', penjelasan alternatif yang masuk akal:",options:["ia sedang marah padamu karena kejadian kemarin yang kamu lupakan","ia tidak melihat atau mendengarmu karena ramai & buru-buru","ia memang tidak suka padamu & sengaja berpura-pura tidak melihat"],answer:1,explain:"Sering ada penjelasan yang lebih sederhana & tidak melibatkan niat buruk. Pertimbangkan itu sebelum menyimpulkan yang menyakitkan.",hint:"Cari penjelasan paling sederhana dulu."},
{n:68,type:"mcq",micro:"'Bisa jadi juga'",q:"Gunanya berlatih mengatakan 'bisa jadi juga karena...' saat menyimpulkan adalah...",options:["membuat kita yakin satu kesimpulan benar sambil menolak penjelasan lain","menghindari berpikir lebih lama sehingga kesimpulan cepat ditetapkan","memaksa kita memikirkan penjelasan lain sebelum mengunci satu kesimpulan"],answer:2,explain:"Kebiasaan memunculkan alternatif adalah rem terhadap kesimpulan tergesa & bias konfirmasi.",hint:"Alat untuk melihat kemungkinan lain."},
{n:69,type:"mcq",micro:"Mungkin vs benar",q:"'Penjelasan ini mungkin' berarti...",options:["penjelasan ini salah satu yang cocok dengan petunjuk, tapi belum tentu yang sebenarnya","penjelasan ini pasti benar sehingga petunjuk lain tidak perlu dicari lagi oleh siapa pun yang sedang memikirkannya","penjelasan ini pasti salah karena belum ada yang membuktikannya dengan bukti yang sempurna sampai sekarang ini"],answer:0,explain:"Beberapa penjelasan berbeda bisa sama-sama 'mungkin'. Petunjuk tambahan yang menentukan mana yang benar.",hint:"Mungkin = kandidat, bukan pemenang."},
{n:70,type:"order",micro:"Memperbaiki kesimpulan",q:"Urutkan langkah saat kesimpulanmu ternyata ditantang petunjuk baru:",items:["Sadari ada petunjuk baru yang tidak cocok dengan kesimpulan lama","Tinjau: apakah petunjuk baru ini kuat & benar?","Sesuaikan atau ganti kesimpulan agar cocok dengan semua petunjuk","Sampaikan kesimpulan yang diperbarui, akui perubahannya"],answer:[0,1,2,3],explain:"Kenali petunjuk baru → nilai → sesuaikan kesimpulan → sampaikan dengan jujur.",hint:"Menyesuaikan kesimpulan ada di tengah-akhir."},
{n:71,type:"tf",micro:"Keras kepala",q:"Benar atau Salah: Terus mempertahankan kesimpulan pertama meskipun banyak petunjuk baru melawannya adalah tanda berpikir yang kuat.",answer:false,explain:"Sebaliknya, itu tanda keras kepala. Kekuatan berpikir justru terlihat dari kesediaan memperbaiki diri saat bukti berubah.",hint:"Kuat = mau berubah saat bukti berubah."},
{n:72,type:"mcq",micro:"Tuduhan dari petunjuk tipis",q:"Uang kas kelas hilang. Kamu ingat Dika kemarin bilang ingin beli sesuatu. Berdasarkan itu saja, kesimpulan yang adil:",options:["Dika pasti pelakunya karena ia baru-baru ini bicara soal membeli sesuatu, jadi sebaiknya langsung dilaporkan kepada guru","'ingin membeli sesuatu' bukan bukti mengambil uang; perlu petunjuk nyata sebelum menuduh siapa pun","Dika boleh dituduh bila ia tidak bisa membuktikan bahwa ia tidak mengambil uang kas itu pada hari kejadian"],answer:1,explain:"Petunjuk yang sangat lemah (keinginan biasa yang dimiliki banyak orang) tidak boleh jadi dasar menuduh.",hint:"Keinginan umum ≠ bukti perbuatan."},
{n:73,type:"mcq",micro:"Kebetulan vs petunjuk",q:"Setiap kali kamu memakai kaus kaki merah, tim kelasmu menang lomba (3 kali). Kesimpulan yang masuk akal:",options:["kaus kaki merah membawa keberuntungan & sebaiknya selalu dipakai saat lomba","kaus kaki merah memengaruhi semangat tim sehingga tim menang tiga kali","kemungkinan besar ini kebetulan; warna kaus kaki tidak memengaruhi hasil lomba"],answer:2,explain:"Dua hal terjadi bersamaan beberapa kali belum berarti yang satu menyebabkan yang lain. Sering itu hanya kebetulan.",hint:"Bersamaan ≠ sebab-akibat."},
{n:74,type:"open",micro:"Saat kamu melompat",q:"Ceritakan satu kali kamu menyimpulkan sesuatu terlalu cepat & ternyata keliru. Apa petunjuk yang kamu punya, apa yang kamu lewatkan, & apa pelajarannya?",explain:"Merefleksikan kesalahan inferensi sendiri membuat kita lebih hati-hati lain kali.",hint:"Petunjuk + yang terlewat + pelajaran.",sample:"Aku pernah menyimpulkan temanku sengaja tidak mengajakku ke acara ulang tahunnya karena aku tidak dapat undangan. Aku kesal seharian. Ternyata undangannya terselip di tas & ia memang mengundangku. Petunjuk yang kupunya: aku tidak menerima undangan. Yang kulewatkan: menanyakan langsung sebelum marah. Pelajaran: periksa dulu sebelum menyimpulkan hal yang menyakitkan."},
{n:75,type:"mcq",micro:"Klaim luar biasa",q:"Temanmu bilang ia melihat harimau berkeliaran di halaman sekolah tadi pagi. Sikap berpikir yang tepat:",options:["semakin luar biasa sebuah klaim, semakin banyak bukti yang wajar diminta sebelum menyimpulkannya benar","percaya begitu saja karena temanmu tidak mungkin berbohong tentang hewan yang dilihatnya di halaman sekolah tadi pagi","tidak mungkin ada harimau di sekolah sehingga temanmu pasti sedang berbohong & tidak perlu didengarkan lagi"],answer:0,explain:"Klaim biasa butuh bukti biasa; klaim luar biasa butuh bukti kuat. Ini menjaga kita dari mudah tertipu maupun terlalu kasar.",hint:"Klaim besar → bukti besar."},
{n:76,type:"tf",micro:"Cerita yang kita bangun",q:"Benar atau Salah: Kadang kita menambahkan detail pada sebuah kejadian dari bayangan kita sendiri, lalu mengira detail itu benar-benar kita lihat.",answer:true,explain:"Ingatan & tafsiran mudah bercampur. Karena itu memisahkan 'yang kulihat' dari 'yang kubayangkan' penting.",hint:"Pikiran suka mengisi kekosongan."},
{n:77,type:"mcq",micro:"Fakta vs cerita",q:"Fakta: 'Bu Guru memanggil Sena ke kantor setelah pelajaran.' Cerita yang mungkin salah kalau langsung dipercaya:",options:["'Sena dipanggil ke kantor Bu Guru.'","'Sena pasti membuat masalah besar & akan dihukum.'","'Pemanggilan itu terjadi setelah pelajaran.'"],answer:1,explain:"'Membuat masalah besar & akan dihukum' adalah cerita yang kita tambahkan. Pemanggilan bisa untuk banyak alasan, termasuk yang baik.",hint:"Mana bagian yang tidak ada di fakta?"},
{n:78,type:"mcq",micro:"Dua penjelasan seimbang",q:"Dua penjelasan sama-sama cocok dengan semua petunjuk yang ada. Langkah terbaik:",options:["lempar koin","pilih yang paling seru","cari petunjuk tambahan yang bisa membedakan keduanya, atau tahan kesimpulan untuk sementara"],answer:2,explain:"Saat bukti belum memihak, jujurlah bahwa keduanya terbuka, & cari petunjuk pembeda.",hint:"Butuh petunjuk yang memisahkan A dari B."},
{n:79,type:"mcq",micro:"Ingin sesuatu jadi benar",q:"Kamu ingin kesimpulan 'lombanya diundur' benar karena kamu belum siap. Bahaya dari keinginan ini:",options:["kamu bisa jadi menonjolkan petunjuk lemah yang mendukung harapanmu & mengabaikan yang melawan","kamu jadi lebih teliti memeriksa semua petunjuk sebelum memutuskan, walaupun hasilnya mungkin tidak sesuai harapanmu","kamu menjadi lebih sabar & menunda kesimpulan sampai semua bukti terkumpul tanpa terpengaruh perasaanmu sendiri"],answer:0,explain:"Keinginan memihak membuat kita menilai petunjuk secara tidak adil. Sadari itu & timbang bukti seolah hasilnya tidak menguntungkanmu.",hint:"Harapan bisa membengkokkan penilaian."},
{n:80,type:"mcq",micro:"Ringkasan Penalaran",q:"Tiga kebiasaan yang menjaga kesimpulan tetap sehat:",options:["cepat memutuskan, percaya diri penuh, tidak berubah pikiran","memunculkan penjelasan alternatif, mencari bukti yang melawan, & bersedia memperbarui kesimpulan","mengikuti dugaan pertama, mengabaikan bukti baru, & memilih yang paling menyenangkan"],answer:1,explain:"Alternatif + uji lawan + kesediaan memperbarui adalah tiga rem terhadap kesalahan inferensi yang paling umum.",hint:"Alternatif, bukti lawan, perbarui."},
{n:81,type:"mcq",micro:"Teka-teki petunjuk",q:"Toples biskuit di dapur kosong. Petunjuk: ada remah biskuit di sofa ruang tamu, remot TV berpindah, & selimut kecil teracak di sofa. Kakak sedang keluar, adik ada di rumah nonton TV. Kesimpulan paling didukung:",options:["kakak makan biskuit lalu menyimpan sisanya di sofa tanpa nonton","adik ketakutan & menyembunyikan biskuit di bawah selimut kecil itu","adik makan biskuit sambil nonton TV di sofa"],answer:2,explain:"Remah di sofa + remot berpindah + selimut teracak + adik di rumah menonton TV semuanya menunjuk ke adik. Kakak sedang tidak di rumah.",hint:"Petunjuk mana yang cocok dengan siapa yang ADA di rumah?"},
{n:82,type:"open",micro:"Analisis adegan lengkap",q:"Adegan: pukul 07.15, gerbang sekolah setengah tertutup, beberapa anak berlari ke arah gerbang, seorang guru piket berdiri sambil mencatat di buku. Tuliskan: (a) 2 pengamatan, (b) kesimpulan paling masuk akal, (c) 1 penjelasan alternatif, (d) 1 informasi yang akan membantumu memastikan.",explain:"Analisis inferensi lengkap memisahkan pengamatan, menyebut kesimpulan terbaik, mengakui alternatif, & tahu bukti apa yang masih kurang.",hint:"Pengamatan → kesimpulan → alternatif → bukti yang kurang.",sample:"(a) Pengamatan: gerbang setengah tertutup pukul 07.15; guru piket mencatat sesuatu di buku sementara beberapa anak berlari masuk. (b) Kesimpulan: bel masuk hampir atau sudah berbunyi, anak-anak itu hampir terlambat, & guru mencatat nama yang terlambat. (c) Alternatif: guru sedang mendata kehadiran biasa, bukan keterlambatan, & gerbang memang selalu setengah tertutup pagi hari. (d) Informasi yang membantu: jam pasti bel masuk sekolah & apa yang sebenarnya ditulis guru di buku itu."},
{n:83,type:"mcq",micro:"Menimbang penjelasan bersaing",q:"Lampu satu ruang kelas mati. Penjelasan A: bohlam putus. Penjelasan B: listrik seluruh sekolah padam. Petunjuk: kelas sebelah lampunya menyala normal. Kesimpulan:",options:["Penjelasan A lebih kuat, karena kalau listrik sekolah padam kelas sebelah juga akan gelap","Penjelasan B lebih kuat, karena listrik sekolah padam menjelaskan semua lampu mati","Keduanya sama kuat, karena tidak ada petunjuk yang membedakan kedua penjelasan itu"],answer:0,explain:"Petunjuk 'kelas sebelah menyala' mematahkan penjelasan B & menguatkan A. Petunjuk pembeda menentukan pemenang.",hint:"Petunjuk mana yang tidak cocok dengan B?"},
{n:84,type:"tf",micro:"Inferensi rantai",q:"Benar atau Salah: Kalau sebuah kesimpulan dibangun di atas kesimpulan lain yang belum pasti, maka kesimpulan akhirnya menjadi lebih rapuh, bukan lebih kuat.",answer:true,explain:"Rantai inferensi hanya sekuat mata rantai terlemahnya. Setiap dugaan yang ditumpuk menambah peluang keliru.",hint:"Dugaan di atas dugaan = makin goyah."},
{n:85,type:"mcq",micro:"Salah membaca nada",q:"Kamu menyimpulkan pesan guru 'Temui saya besok.' bernada marah, lalu cemas semalaman. Langkah yang lebih baik daripada menyimpulkan nada dari teks singkat:",options:["menyimpan kecemasan sendiri & tidak mengatakan apa pun kepada guru sampai bertemu besok pagi di sekolah dengan perasaan gelisah","membalas dengan sopan menanyakan 'Baik, Bu. Apakah ada hal khusus yang perlu saya siapkan?'","menyebarkan kekhawatiran ke teman-teman supaya mereka ikut menebak maksud guru lalu memutuskan bersama-sama apa yang harus dilakukan"],answer:1,explain:"Teks singkat hampir tidak membawa petunjuk nada. Bertanya langsung mengganti tebakan dengan informasi.",hint:"Ganti tebakan nada dengan pertanyaan."},
{n:86,type:"order",micro:"Proses inferensi utuh",q:"Urutkan seluruh proses menarik kesimpulan yang cermat:",items:["Kumpulkan & catat semua petunjuk yang teramati","Pisahkan pengamatan dari tafsiran","Munculkan beberapa penjelasan yang mungkin","Timbang penjelasan dengan petunjuk pendukung & petunjuk yang melawan","Pilih kesimpulan paling didukung, atau tahan bila bukti belum cukup","Cari informasi tambahan & perbarui bila perlu"],answer:[0,1,2,3,4,5],explain:"Kumpulkan → pisahkan → munculkan alternatif → timbang → pilih/tahan → perbarui.",hint:"Mengumpulkan petunjuk pertama, memperbarui terakhir."},
{n:87,type:"mcq",micro:"Inferensi + bertanya",q:"Inferensi & mengajukan pertanyaan bekerja paling baik bila...",options:["kamu menebak tanpa pernah bertanya & menganggap tebakan itu pasti benar","kamu bertanya terus tanpa memikirkan petunjuk sama sekali sebelumnya","kamu memakai inferensi untuk membuat dugaan, lalu bertanya untuk mengujinya"],answer:2,explain:"Inferensi menghasilkan dugaan; pertanyaan mengujinya. Keduanya bersama membuat kesimpulan lebih andal.",hint:"Duga lewat inferensi, uji lewat pertanyaan."},
{n:88,type:"open",micro:"Rancang pengujian",q:"Kamu menduga 'tanaman di pojok kelas layu karena kurang cahaya matahari'. Tuliskan 2 petunjuk yang akan kamu kumpulkan & 1 percobaan sederhana untuk menguji dugaan itu.",explain:"Menguji inferensi berarti mengumpulkan petunjuk pembeda & bila mungkin melakukan percobaan terkendali.",hint:"2 petunjuk + 1 percobaan sederhana.",sample:"Petunjuk yang kukumpulkan: (1) seberapa jauh tanaman dari jendela & berapa lama pojok itu kena cahaya tiap hari, (2) apakah tanahnya lembap atau kering & apakah ada tanaman sejenis di tempat terang yang tumbuh sehat. Percobaan: pindahkan tanaman ke dekat jendela selama dua minggu sambil menyiram seperti biasa; jika membaik, dugaan kurang cahaya menguat."},
{n:89,type:"mcq",micro:"Kapan tidak menyimpulkan",q:"Situasi di mana sebaiknya kamu TIDAK menarik kesimpulan dulu:",options:["saat petunjuk sedikit, bertentangan, & keputusannya bisa merugikan orang lain","saat petunjuknya banyak, jelas, & tidak merugikan siapa pun","saat kamu sudah merasa yakin & tidak ingin mengubah pendapat lagi"],answer:0,explain:"Bukti tipis + taruhan tinggi (nama baik, hukuman, hubungan) adalah alasan kuat untuk menahan kesimpulan sampai bukti cukup.",hint:"Bukti tipis + akibat besar = tahan dulu."},
{n:90,type:"tf",micro:"Kesimpulan & rasa hormat",q:"Benar atau Salah: Menyampaikan kesimpulan tentang orang lain sebagai 'kemungkinan' & bukan 'kepastian' adalah cara yang lebih adil & sopan.",answer:true,explain:"Bahasa yang berhati-hati ('sepertinya', 'mungkin karena') menjaga ruang bila kita keliru & menghormati orang yang dibicarakan.",hint:"'Mungkin' lebih adil daripada 'pasti'."},
{n:91,type:"mcq",micro:"Kesaksian vs petunjuk fisik",q:"Dua anak memberi cerita berbeda soal siapa yang memecahkan vas. Petunjuk fisik: pecahan vas ada di sisi ruangan tempat anak pertama berdiri, & hanya jejak sepatunya di dekat situ. Kesimpulan yang lebih didukung:",options:["cerita anak kedua pasti benar karena ia berbicara lebih tenang & lebih sopan, sehingga petunjuk fisik tidak perlu dipertimbangkan","petunjuk fisik lebih mendukung keterlibatan anak pertama, walau tetap perlu dikonfirmasi dengan tenang","tidak ada gunanya memeriksa petunjuk fisik karena cerita anak pasti lebih penting daripada benda-benda di ruangan itu"],answer:1,explain:"Saat kesaksian bertentangan, petunjuk fisik yang objektif membantu menimbang. Tetap konfirmasi, jangan langsung menghukum.",hint:"Bukti fisik menimbang kesaksian yang berbeda."},
{n:92,type:"mcq",micro:"Inferensi vs asumsi",q:"Beda inferensi & asumsi:",options:["inferensi selalu salah dan asumsi selalu benar karena asumsi sudah dipikirkan lama oleh orang yang membuatnya","inferensi & asumsi sama saja, hanya berbeda cara menuliskannya di kertas sehingga tidak perlu dibedakan dalam berpikir","inferensi dibangun dari petunjuk yang teramati; asumsi adalah hal yang kita anggap benar begitu saja tanpa memeriksanya"],answer:2,explain:"Inferensi punya jejak petunjuk yang bisa ditelusuri. Asumsi sering tak terlihat & tak teruji — berbahaya bila keliru.",hint:"Punya petunjuk vs dianggap benar saja."},
{n:93,type:"mcq",micro:"Memeriksa asumsi tersembunyi",q:"Kamu menyimpulkan 'Nadia tidak mengerjakan PR' karena ia tidak mengumpulkan buku. Asumsi tersembunyi yang perlu diperiksa:",options:["bahwa 'tidak mengumpulkan buku' selalu berarti 'tidak mengerjakan' — padahal bisa saja bukunya tertinggal atau sudah dikumpulkan lewat cara lain","bahwa Nadia adalah nama seseorang","bahwa PR itu ada"],answer:0,explain:"Setiap inferensi berdiri di atas asumsi. Memeriksanya ('apa lagi yang bisa membuat buku tak terkumpul?') memperkuat penalaran.",hint:"Apa yang kamu anggap otomatis benar di sini?"},
{n:94,type:"mcq",micro:"Ilmuwan meninjau hipotesis",q:"Seorang murid menduga 'biji tumbuh lebih cepat dengan pupuk'. Setelah percobaan, tanaman berpupuk & tanpa pupuk tumbuh sama. Sikap ilmiah:",options:["menyimpulkan percobaannya pasti salah & mengulangnya dengan mengubah hasil agar sesuai dugaan","menerima bahwa dugaan tidak terdukung kali ini & memikirkan penjelasan atau percobaan berikutnya","tetap bersikeras pupuk berpengaruh & menganggap tanaman tanpa pupuk curang"],answer:1,explain:"Inferensi ilmiah tunduk pada data. Bukti yang melawan dugaan adalah informasi berharga, bukan sesuatu untuk ditutupi.",hint:"Data mengalahkan dugaan awal."},
{n:95,type:"tf",micro:"Petunjuk yang menyesatkan",q:"Benar atau Salah: Kadang petunjuk yang tampak jelas justru menyesatkan, sehingga kesimpulan yang paling 'kelihatan benar' pada pandangan pertama ternyata keliru.",answer:true,explain:"Karena itu berpikir kritis menimbang semua petunjuk & menguji penjelasan, bukan mengikuti kesan pertama.",hint:"Kesan pertama bisa jebakan."},
{n:96,type:"mcq",micro:"Menilai orang dari sekilas",q:"Kamu melihat anak baru duduk sendiri & tidak bicara saat istirahat pertama. Kesimpulan yang adil & berhati-hati:",options:["anak itu pasti sombong & tidak mau berteman, jadi sebaiknya dijauhi saja","anak itu pasti sedih karena tidak punya teman, sehingga perlu dihibur dengan cara dramatis","satu pengamatan singkat belum cukup; anak baru sering sungkan di hari pertama — beri kesempatan & sapa dulu"],answer:2,explain:"Perilaku sekali dalam situasi tertentu (hari pertama, sendirian) adalah petunjuk sangat tipis untuk menyimpulkan sifat seseorang.",hint:"Hari pertama ≠ kepribadian seumur hidup."},
{n:97,type:"mcq",micro:"Kesimpulan terkuat",q:"Petunjuk: (1) buku perpustakaan terlambat dikembalikan 5 anak bulan ini, (2) semuanya dari kelas yang jadwal kunjung perpustakaannya dihapus bulan ini, (3) bulan lalu tidak ada keterlambatan dari kelas itu. Kesimpulan terkuat:",options:["hilangnya jadwal kunjung rutin kemungkinan membuat mereka lupa mengembalikan tepat waktu","anak-anak itu malas membaca buku & tidak peduli pada aturan perpustakaan","buku-buku itu pasti sudah rusak sehingga tidak bisa dikembalikan tepat waktu"],answer:0,explain:"Ketiga petunjuk (waktu mulai, kelas yang sama, tidak ada masalah sebelumnya) sejalan menunjuk pada perubahan jadwal sebagai penyebab.",hint:"Apa yang berubah tepat saat masalah mulai?"},
{n:98,type:"order",micro:"Kasus hilangnya spidol",q:"Spidol papan tulis sering hilang dari kelas. Urutkan langkah menyelidiki dengan berpikir kritis:",items:["Catat pola: hari apa, jam pelajaran apa, sisa berapa","Kumpulkan penjelasan yang mungkin (terbawa pulang, pindah kelas lain, habis tinta lalu dibuang)","Cari petunjuk pembeda untuk tiap penjelasan","Simpulkan penyebab paling didukung & usulkan solusi, siap direvisi bila salah"],answer:[0,1,2,3],explain:"Pola → daftar penjelasan → petunjuk pembeda → kesimpulan yang bisa direvisi.",hint:"Mulai dari mencatat pola."},
{n:99,type:"open",micro:"Rencana berpikir",q:"Tuliskan panduan pribadimu (3-4 langkah) untuk dipakai lain kali sebelum kamu menyimpulkan sesuatu yang penting tentang orang atau kejadian.",explain:"Panduan pribadi yang ringkas membuat kebiasaan berpikir hati-hati lebih mudah dijalankan saat situasi menekan.",hint:"3-4 langkah, dengan katamu sendiri.",sample:"1) Tulis dulu apa yang benar-benar kulihat/dengar, pisahkan dari tafsiranku. 2) Sebut minimal dua penjelasan lain, termasuk yang tidak menyalahkan siapa pun. 3) Tanyakan: petunjukku cukup & relevan? Adakah bukti yang melawan? 4) Kalau menyangkut orang, konfirmasi dengan bertanya sebelum bertindak, & sampaikan kesimpulan sebagai kemungkinan."},
{n:100,type:"mcq",micro:"Ringkasan Tantangan",q:"Inti keterampilan menarik kesimpulan yang matang adalah...",options:["mengambil kesimpulan secepat mungkin dari petunjuk pertama yang kamu lihat, lalu mempertahankannya agar kamu terlihat yakin & konsisten di depan teman","membangun kesimpulan dari petunjuk yang cukup & relevan, mempertimbangkan alternatif, menahan diri saat bukti kurang, & bersedia memperbaikinya","menunggu hingga semua bukti sempurna terkumpul baru berani berpikir, sehingga kamu tidak pernah menyimpulkan apa pun & tidak pernah bertindak"],answer:1,explain:"Inferensi yang baik adalah jembatan yang kuat namun bisa diperbaiki: didasari bukti, terbuka pada alternatif, & tunduk pada petunjuk baru.",hint:"Bukti cukup, alternatif, tahan diri, perbaiki."},
];
